// The Next.js adapter, which is a subpath of the package and not its root.
//
// Spelled as a subpath on purpose: the name lives at `@trpc/server/adapters/next`,
// and putting it on the root would be declaring a name the library never exported
// there, which a stub may never do. It is also the name a real repository wraps —
// its own three-line `createNextApiHandler` around this one — and surviving that
// wrapping is what the mount reading has to do.

import type { AnyRouter } from '../index.js';

export declare function createNextApiHandler(options: {
  router: AnyRouter;
  createContext?: () => unknown;
}): (req: unknown, res: unknown) => unknown;
